// @ts-check
/**
 * The static SVG art (docs/art.md §9): friends' eggs, cosmetics with the crowned stage's crown,
 * and sticker art, generated by code into assets/art/{eggs,cosmetics,stickers}/.
 *
 *   node scripts/art/svg/generate.mjs          write the files and assets/art/svg-provenance.json
 *   node scripts/art/svg/generate.mjs --check  fail when a committed file is not the generator's
 *
 * Generated art is reproducible (docs/assets.md §5, rule 1): the output depends only on this code,
 * with deterministic trigonometry and number formatting, so every OS writes the same bytes. The
 * art catalog (scripts/art/catalog.mjs) lists every file and checks it against the generator too.
 */
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { isMain, repositoryRoot } from '../../lib/tools.mjs';
import { COSMETIC_DESIGNS, COSMETIC_SIZE } from './cosmetics.mjs';
import { EGG_DESIGNS, EGG_HEIGHT, EGG_WIDTH, drawEgg } from './eggs.mjs';
import { STICKER_DESIGNS, STICKER_SIZE } from './stickers.mjs';
import { svgFile } from './lib/xml.mjs';

export const SVG_FOLDERS = ['eggs', 'cosmetics', 'stickers'];
export const SVG_PROVENANCE_PATH = 'assets/art/svg-provenance.json';
const GENERATOR = 'scripts/art/svg/generate.mjs';

/** @typedef {{ id: string; file: string; width: number; height: number; svg: string }} SvgArt */

/** @param {string} a @param {string} b */
function byCodeUnits(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}

/**
 * Every static SVG, sorted by art ID.
 *
 * @returns {SvgArt[]}
 */
export function renderSvgArt() {
  /** @type {SvgArt[]} */
  const art = [];
  for (const egg of EGG_DESIGNS) {
    art.push({
      id: `egg/${egg.id}`,
      file: `eggs/${egg.id}.svg`,
      width: EGG_WIDTH,
      height: EGG_HEIGHT,
      svg: svgFile(EGG_WIDTH, EGG_HEIGHT, drawEgg(egg)),
    });
  }
  for (const item of COSMETIC_DESIGNS) {
    art.push({
      id: `cosmetic/${item.id}`,
      file: `cosmetics/${item.id}.svg`,
      width: COSMETIC_SIZE,
      height: COSMETIC_SIZE,
      svg: svgFile(COSMETIC_SIZE, COSMETIC_SIZE, item.draw()),
    });
  }
  for (const sticker of STICKER_DESIGNS) {
    art.push({
      id: `sticker/${sticker.id}`,
      file: `stickers/${sticker.id}.svg`,
      width: STICKER_SIZE,
      height: STICKER_SIZE,
      svg: svgFile(STICKER_SIZE, STICKER_SIZE, sticker.draw()),
    });
  }
  const ids = new Set();
  for (const item of art) {
    if (ids.has(item.id)) throw new Error(`Two SVG designs for ${item.id}.`);
    ids.add(item.id);
  }
  return art.sort((a, b) => byCodeUnits(a.id, b.id));
}

/** @param {string} text */
function sha256(text) {
  return createHash('sha256').update(text, 'utf8').digest('hex');
}

/**
 * The provenance record of the generated files (never shipped).
 *
 * @param {SvgArt[]} art
 */
export function svgProvenance(art) {
  return `${JSON.stringify(
    {
      schema: 'pearl-sea-svg-provenance/1',
      description:
        'Static SVG art generated by code, never by a model. Regenerate with node ' +
        `${GENERATOR}; --check (and the art catalog check) compares every committed file with the ` +
        "generator's output byte for byte.",
      generator: GENERATOR,
      files: art.map((item) => ({
        id: item.id,
        file: item.file,
        width: item.width,
        height: item.height,
        bytes: Buffer.byteLength(item.svg, 'utf8'),
        sha256: sha256(item.svg),
      })),
    },
    null,
    2,
  )}\n`;
}

/**
 * Compares the committed files with the generator's output.
 *
 * @param {string} [root]
 * @returns {string[]} problems
 */
export function checkSvgArt(root = repositoryRoot) {
  const art = renderSvgArt();
  /** @type {string[]} */
  const problems = [];
  const expected = new Set(art.map((item) => item.file));
  for (const item of art) {
    let current = '';
    try {
      current = readFileSync(join(root, 'assets', 'art', ...item.file.split('/')), 'utf8');
    } catch {
      problems.push(`assets/art/${item.file} is missing: run node ${GENERATOR}.`);
      continue;
    }
    if (current !== item.svg)
      problems.push(`assets/art/${item.file} is not the generator's output.`);
  }
  for (const folder of SVG_FOLDERS) {
    let names = [];
    try {
      names = readdirSync(join(root, 'assets', 'art', folder));
    } catch {
      continue;
    }
    for (const name of names) {
      if (!expected.has(`${folder}/${name}`))
        problems.push(`assets/art/${folder}/${name} has no design.`);
    }
  }
  let provenance = '';
  try {
    provenance = readFileSync(join(root, ...SVG_PROVENANCE_PATH.split('/')), 'utf8');
  } catch {
    problems.push(`${SVG_PROVENANCE_PATH} is missing.`);
  }
  if (provenance !== '' && provenance !== svgProvenance(art)) {
    problems.push(`${SVG_PROVENANCE_PATH} is stale: run node ${GENERATOR}.`);
  }
  return problems;
}

/**
 * Writes every file, removes files without a design, and writes the provenance record.
 *
 * @param {string} [root]
 */
export function writeSvgArt(root = repositoryRoot) {
  const art = renderSvgArt();
  for (const folder of SVG_FOLDERS)
    rmSync(join(root, 'assets', 'art', folder), { recursive: true, force: true });
  for (const item of art) {
    const path = join(root, 'assets', 'art', ...item.file.split('/'));
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, item.svg);
  }
  writeFileSync(join(root, ...SVG_PROVENANCE_PATH.split('/')), svgProvenance(art));
  return art;
}

if (isMain(import.meta.url)) {
  if (process.argv.includes('--check')) {
    const problems = checkSvgArt();
    if (problems.length > 0) {
      console.error(problems.map((problem) => `- ${problem}`).join('\n'));
      process.exit(1);
    }
    console.log(`Checked ${renderSvgArt().length} SVG files.`);
  } else {
    const art = writeSvgArt();
    const bytes = art.reduce((sum, item) => sum + Buffer.byteLength(item.svg, 'utf8'), 0);
    console.log(`Wrote ${art.length} SVG files (${(bytes / 1024).toFixed(1)} KiB).`);
  }
}
